  return row['MA_20'] > row['MA_50'] and row['MACD'] > 0 and row['Stochastic_%K'] > 20

def short_entry(row):
  return row['MA_20'] < row['MA_50'] and row['MACD'] < 0 and row['Stochastic_%K'] < 80

def long_exit(row):
  return row['MA_20'] < row['MA_50'] or row['Stochastic_%K'] > 80

def short_exit(row):
